    # Calculate actual errors against ground truth
    memory_errors = sum(
        1
        for (_, ground_truth, _), decision in zip(scenario_data, memory_decisions)
        if decision != ground_truth
    )
    actual_error_rate = memory_errors / len(scenario_data)

