    k1_baseline = (
        avg_time_baseline * (1.0 + PHASE_8_0_ERROR_RATE)
    ) / CLASSICAL_BASELINE_MS
    k1_improvement_pct = ((k1_baseline - k1_memory) / k1_baseline) * 100

