    print(
        f"  Time reduction:            {time_reduction_pct:.1%} {'✅' if time_reduction_pct >= 0.15 else '❌'} (target ≥ 15%)"
    )
    print()
    print("Memory Performance:")
    print(
        f"  Cache hit rate:            {cache_hit_rate:.1%} {'✅' if cache_hit_rate >= 0.30 else '❌'} (target > 30%)"
    )
